/**
 * @summary List newsletter subscribers
 */
export const getListNewsletterSubscribersUrl = (
  params?: ListNewsletterSubscribersParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/newsletter/subscribers?${stringifiedParams}`
    : `/api/newsletter/subscribers`;
};

export const listNewsletterSubscribers = async (
  params?: ListNewsletterSubscribersParams,
  options?: RequestInit,
): Promise<NewsletterSubscriberListResponse> => {
  return customFetch<NewsletterSubscriberListResponse>(
    getListNewsletterSubscribersUrl(params),
    {
      ...options,
      method: "GET",
    },
  );
};

